from collections import deque


def minutes_to_burn(field: list[str]) -> int:
    grid = [list(row) for row in field]
    queue, trees = deque(), 0
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == "F":
                queue.append((r, c, 0))          # every fire starts at minute 0
            elif cell == "T":
                trees += 1
    minute = 0
    while queue:
        r, c, minute = queue.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == "T":
                grid[nr][nc] = "F"               # mark when queued, not when popped
                trees -= 1
                queue.append((nr, nc, minute + 1))
    return minute if trees == 0 else -1

