from collections import deque


def minutes_to_burn(field: list[str]) -> int:
    rows, cols = len(field), len(field[0]) if field else 0
    trees = sum(row.count("T") for row in field)
    first = {}                               # tree -> earliest minute any fire reaches it
    for fr in range(rows):
        for fc in range(cols):
            if field[fr][fc] != "F":
                continue
            minute, queue = {(fr, fc): 0}, deque([(fr, fc)])
            while queue:                     # a whole BFS for this one fire
                r, c = queue.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and field[nr][nc] == "T" and (nr, nc) not in minute:
                        minute[(nr, nc)] = minute[(r, c)] + 1
                        first[(nr, nc)] = min(first.get((nr, nc), minute[(nr, nc)]), minute[(nr, nc)])
                        queue.append((nr, nc))
    if len(first) < trees:
        return -1
    return max(first.values(), default=0)
